import{_ as e,o,c as a,a2 as s}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Making Ceph Fast in the Face of Failure - Neha Ojha, Red Hat","description":"","frontmatter":{"title":"Making Ceph Fast in the Face of Failure - Neha Ojha, Red Hat","date":"2019-05-24T00:00:00.000Z","updated":"2019-05-24T00:00:00.000Z","tags":["Ceph","分布式存储","故障处理","性能优化","日志恢复"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/Making_Ceph_Fast_in_the_Face_of_Failure_-_Neha_Ojha_Red_Hat.md","filePath":"posts/2019/Making_Ceph_Fast_in_the_Face_of_Failure_-_Neha_Ojha_Red_Hat.md","lastUpdated":1780459816000}'),n={name:"posts/2019/Making_Ceph_Fast_in_the_Face_of_Failure_-_Neha_Ojha_Red_Hat.md"};function _(r,t,i,p,l,g){return o(),a("div",null,[...t[0]||(t[0]=[s("<p>会议纪要：</p><p><strong>会议主题</strong>： Ceph 分布式存储在故障处理和性能优化方面的进展</p><p><strong>参会人员</strong>： Neha Ojha（Ceph 技术负责人），Red Hat 高级软件工程师</p><p><strong>会议内容</strong>：</p><p><strong>一、故障处理机制</strong></p><ol><li><strong>日志恢复</strong>： 通过分析 OSD 的 PG 日志进行数据恢复，速度快，但可能因日志过长导致内存溢出。</li><li><strong>填充恢复</strong>： 通过比较磁盘上的对象状态进行数据恢复，速度慢，但不会出现日志溢出问题。</li></ol><p><strong>二、Ceph 故障处理优化</strong></p><ol><li><strong>早期版本问题</strong>： 在 Ceph 早期版本中，故障恢复和填充操作会影响客户端 I/O，导致性能下降。</li><li><strong>Infernalis 版本改进</strong>： 默认设置优化了 OSD 最大填充和 OST 恢复最大活跃参数，提高了性能。</li><li><strong>Luminous 版本改进</strong>： 引入 OST 恢复扫描选项，通过控制恢复速率来平衡客户端 I/O 和恢复操作。</li><li><strong>Mimic 版本改进</strong>： 引入异步恢复，通过推迟对非活跃 OSD 的恢复操作来提高性能。</li><li><strong>Nautilus 版本改进</strong>： 实现了 PG 日志长度硬限制，防止日志溢出；引入强制恢复和强制填充选项，在池级别进行操作；改进了异步恢复的计算方法。</li></ol><p><strong>三、未来工作计划</strong></p><ol><li><strong>部分恢复</strong>： 仅复制修改过的对象部分，提高效率。</li><li><strong>擦除编码池恢复</strong>： 在擦除编码池中进行更小的数据恢复。</li><li><strong>自适应恢复</strong>： 根据客户端 I/O 量动态调整恢复速率。</li><li><strong>全功能 QoS 项目</strong>： 提高资源分配效率，保证关键数据优先恢复。</li></ol><p><strong>四、总结</strong></p><p>Ceph 分布式存储在故障处理和性能优化方面取得了显著进展，通过不断改进和优化，Ceph 的可靠性和性能得到了显著提升。</p><p><strong>关键词</strong>： Ceph、分布式存储、故障处理、性能优化、日志恢复、填充恢复、异步恢复、QoS、自适应恢复</p>",13)])])}const c=e(n,[["render",_]]);export{d as __pageData,c as default};
